R=C=10; seen=set(); objs=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c)); cells=[]
   while st:
    x,y=st.pop();cells.append((x,y))
    for p in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     a,b=p
     if 0<=a<R and 0<=b<C and p not in seen and grid[a][b]==v:seen.add(p);st.append(p)
   objs.append((v,cells))
objs=[(v,c) for v,c in objs]
# process rightmost first, each object to maximal position
placed=[]
for v,cells in sorted(objs,key=lambda z:max(y for x,y in z[1]),reverse=True):
 d=0
 while max(y for x,y in cells)+d+1<C and all((x,y+d+1) not in occ for _,occ in placed for x,y in occ): d+=1
 new=[(x,y+d) for x,y in cells]; placed.append((v,new)); print(v,cells,'shift',d)
out=[[0]*C for _ in range(R)]
for v,cells in placed:
 for x,y in cells:out[x][y]=v
print(out)
